/// Echo service: status from the path, fails on `/err`, reports the active trace id.
#[derive(Clone)]
struct Echo;

impl Service<http::Request<()>> for Echo {
    type Response = http::Response<String>;
    type Error = String;
    type Future = Ready<Result<Self::Response, Self::Error>>;
    fn poll_ready(&mut self, _cx: &mut TaskContext<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }
    fn call(&mut self, req: http::Request<()>) -> Self::Future {
        let trace = current_trace_id().unwrap_or_default();
        ready(match req.uri().path() {
            "/err" => Err("handler failed".to_string()),
            "/500" => Ok(http::Response::builder().status(500).body(trace).unwrap()),
            _ => Ok(http::Response::builder().status(200).body(trace).unwrap()),
        })
    }
}

async fn call<S>(svc: &mut S, req: http::Request<()>) -> Result<S::Response, S::Error>
where
    S: Service<http::Request<()>>,
{
    futures::future::poll_fn(|cx| svc.poll_ready(cx)).await?;
    svc.call(req).await
}

#[tokio::test]
async fn tower_layer_creates_server_spans() {
    let (exp, handle) = setup();
    let layer = TraceLayer::new()
        .with_tracer(handle.tracer("tower", None))
        .with_span_namer(|m, u| format!("{m} {}", u.path()));
    assert!(format!("{layer:?}").contains("TraceLayer"));
    let mut svc = layer.layer(Echo);
    assert!(format!("{svc:?}").contains("TraceService"));
    let req = http::Request::builder()
        .uri("https://api.example.com/ok?x=1")
        .header(
            "traceparent",
            "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
        )
        .header("user-agent", "test-agent")
        .body(())
        .unwrap();
    let resp = call(&mut svc, req).await.unwrap();
    assert_eq!(
        resp.body(),
        "4bf92f3577b34da6a3ce929d0e0e4736",
        "handler runs inside the span"
    );
    let req = http::Request::builder()
        .uri("/500")
        .header("host", "svc.local:8080")
        .body(())
        .unwrap();
    assert_eq!(call(&mut svc, req).await.unwrap().status(), 500);
    let req = http::Request::builder().uri("/err").body(()).unwrap();
    assert!(call(&mut svc, req).await.is_err());
    // Default namer and global tracer.
    let mut plain = TraceLayer::default().layer(Echo);
    let req = http::Request::builder().uri("/ok").body(()).unwrap();
    let fut = plain.call(req);
    assert!(format!("{fut:?}").contains("TraceFuture"));
    fut.await.unwrap();

    handle.force_flush(None).await.unwrap();
    let spans = exp.spans();
    let ok = spans
        .iter()
        .find(|s| s.name == "GET /ok" && s.attributes.contains_key("url.scheme"))
        .unwrap();
    assert_eq!(ok.kind, SpanKind::Server);
    assert_eq!(ok.trace_id, "4bf92f3577b34da6a3ce929d0e0e4736");
    assert_eq!(ok.parent_span_id.as_deref(), Some("00f067aa0ba902b7"));
    assert_eq!(ok.attributes["http.request.method"], "GET");
    assert_eq!(ok.attributes["url.path"], "/ok");
    assert_eq!(ok.attributes["url.scheme"], "https");
    assert_eq!(ok.attributes["server.address"], "api.example.com");
    assert_eq!(ok.attributes["user_agent.original"], "test-agent");
    assert_eq!(ok.attributes["http.response.status_code"], 200);
    assert_eq!(ok.status.code, StatusCode::Unset);
    let e500 = spans.iter().find(|s| s.name == "GET /500").unwrap();
    assert_eq!(e500.status.code, StatusCode::Error);
    assert_eq!(e500.attributes["server.address"], "svc.local");
    let err = spans.iter().find(|s| s.name == "GET /err").unwrap();
    assert_eq!(err.status.message.as_deref(), Some("handler failed"));
    handle.shutdown().await.unwrap();
}

#[tokio::test]
async fn reqwest_middleware_creates_client_spans() {
    let (exp, handle) = setup();
    let server = MockServer::start().await;
    Mock::given(path("/ok"))
        .and(header_exists("traceparent"))
        .respond_with(ResponseTemplate::new(200))
        .mount(&server)
        .await;
    Mock::given(path("/missing"))
        .respond_with(ResponseTemplate::new(404))
        .mount(&server)
        .await;
    let mw = TracingMiddleware::new().with_tracer(handle.tracer("reqwest", None));
    assert!(format!("{mw:?}").contains("TracingMiddleware"));
    let client = reqwest_middleware::ClientBuilder::new(reqwest::Client::new())
        .with(mw)
        .build();
    let resp = client
        .get(format!("{}/ok?token=abc", server.uri()))
        .send()
        .await
        .unwrap();
    assert_eq!(resp.status(), 200, "traceparent header was injected");
    let resp = client
        .get(format!("{}/missing", server.uri()))
        .send()
        .await
        .unwrap();
    assert_eq!(resp.status(), 404);
    assert!(client.get("http://127.0.0.1:1/").send().await.is_err());
    let global = reqwest_middleware::ClientBuilder::new(reqwest::Client::new())
        .with(TracingMiddleware::default())
        .build();
    let _ = global.get(format!("{}/ok", server.uri())).send().await;

    handle.force_flush(None).await.unwrap();
    let spans = exp.spans();
    assert_eq!(spans.len(), 3);
    assert!(spans
        .iter()
        .all(|s| s.kind == SpanKind::Client && s.name == "GET"));
    let ok = &spans[0];
    assert_eq!(ok.attributes["http.response.status_code"], 200);
    assert!(
        ok.attributes["url.full"]
            .as_str()
            .unwrap()
            .contains("token=%5BREDACTED%5D")
            || ok.attributes["url.full"]
                .as_str()
                .unwrap()
                .contains("[REDACTED]")
    );
    assert_eq!(ok.attributes["server.address"], "127.0.0.1");
    assert!(ok.attributes.contains_key("server.port"));
    assert_eq!(spans[1].status.code, StatusCode::Error);
    assert_eq!(spans[2].status.code, StatusCode::Error);
    assert_eq!(spans[2].events[0].name, "exception");
    handle.shutdown().await.unwrap();
}
